import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.Zkdr1e1x.js";const h=JSON.parse('{"title":"ADR 0001: Standardize Testing Framework on JUnit 5 Jupiter","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-use-junit-5-jupiter.md","filePath":"adr/0001-use-junit-5-jupiter.md"}'),n={name:"adr/0001-use-junit-5-jupiter.md"};function o(s,e,d,c,u,l){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0001-standardize-testing-framework-on-junit-5-jupiter" tabindex="-1">ADR 0001: Standardize Testing Framework on JUnit 5 Jupiter <a class="header-anchor" href="#adr-0001-standardize-testing-framework-on-junit-5-jupiter" aria-label="Permalink to &quot;ADR 0001: Standardize Testing Framework on JUnit 5 Jupiter&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The legacy repository contained only one test class written in JUnit 4 (<code>org.junit.Test</code>). Modern Java testing demands parameterization, dynamic tests, structured execution, and superior assertion engines (AssertJ).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Upgrade the test suite to JUnit 5 (<code>junit-jupiter</code>), eliminate all JUnit 4 dependencies, and pair tests with AssertJ for readable assertions.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>: Native support for <code>@DisplayName</code>, <code>@Nested</code> suites, <code>@Timeout</code> for concurrency safety, and <code>@ParameterizedTest</code>.</li><li><strong>Negative</strong>: Legacy tests require namespace updates (<code>org.junit.Test</code> to <code>org.junit.jupiter.api.Test</code>).</li></ul>',9)])])}const m=t(n,[["render",o]]);export{h as __pageData,m as default};
